import java.io.*;

class Spell implements Serializable {
    String name; int power;
    Spell(String n, int p) { name=n; power=p; }
}

// Write
try (ObjectOutputStream oos = new ObjectOutputStream(
        new FileOutputStream("spell.ser"))) {
    oos.writeObject(new Spell("Fireball", 80));
}

// Read
try (ObjectInputStream ois = new ObjectInputStream(
        new FileInputStream("spell.ser"))) {
    Spell s = (Spell) ois.readObject();
    System.out.println(s.name + ": " + s.power);
}

