import java.io.*;
import java.nio.file.*;

public class FilePaths {
    static class Wizard implements Serializable {
        String name; int level;
        Wizard(String n, int l) { name=n; level=l; }
    }
    public static void main(String[] args) throws Exception {
        Path temp = Files.createTempFile("wizard", ".ser");
        try (ObjectOutputStream oos = new ObjectOutputStream(
                new FileOutputStream(temp.toFile()))) {
            oos.writeObject(new Wizard("Merlin", 99));
        }
        try (ObjectInputStream ois = new ObjectInputStream(
                new FileInputStream(temp.toFile()))) {
            Wizard w = (Wizard) ois.readObject();
            System.out.println(w.name);
            System.out.println(w.level);
        }
        Files.delete(temp);
    }
}
